CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, full_name VARCHAR(140) NOT NULL, email VARCHAR(255) NOT NULL, phone VARCHAR(20) NOT NULL, password_hash VARCHAR(100) NOT NULL, role VARCHAR(30) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uk_users_email UNIQUE(email), CONSTRAINT uk_users_phone UNIQUE(phone));
CREATE TABLE refresh_sessions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, token_hash VARCHAR(100) NOT NULL, expires_at TIMESTAMP NOT NULL, revoked BOOLEAN NOT NULL DEFAULT FALSE, CONSTRAINT fk_refresh_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT uk_refresh_token UNIQUE(token_hash));
CREATE INDEX idx_refresh_user_active ON refresh_sessions(user_id,revoked,expires_at);
